std::string binaryArchitecture(const Binary& b){if(b.language.starts_with("AARCH64:"))return "arm64";if(b.language.starts_with("ARM:"))return b.language.find(":v8T:")!=std::string::npos?"thumb":"arm";if(b.language.starts_with("RISCV:"))return b.bits==64?"riscv64":"riscv32";if(b.language.starts_with("MIPS:"))return b.bits==64?"mips64":"mips32";return b.bits==64?"x64":"x86";}
