uint32_t swap32(uint32_t v){return (v>>24)|((v>>8)&0xff00)|((v<<8)&0xff0000)|(v<<24);}
uint64_t swap64(uint64_t v){return uint64_t(swap32(uint32_t(v)))<<32|swap32(uint32_t(v>>32));}
std::string cpuLanguage(uint32_t cpu){switch(cpu){case 7:return "x86:LE:32:default:gcc";case 0x1000007:return "x86:LE:64:default:gcc";case 12:return "ARM:LE:32:v8:default";case 0x100000c:return "AARCH64:LE:64:v8A:default";default:throw std::runtime_error("Unsupported Mach-O CPU type");}}
