std::vector<Instruction> decodeArchitectureListing(const Binary& b,Address va,size_t count,const std::function<bool()>& cancelled){Decoder d(b);if(va%d.alignment)throw std::runtime_error("Instruction address is not aligned for this CPU");std::vector<Instruction> rows;rows.reserve(count);const char* hexchars="0123456789abcdef";for(size_t i=0;i<count;++i){if((i&255)==0&&cancelled())throw std::runtime_error("Operation cancelled");auto* s=b.section(va);if(!s||!s->executable)break;uint8_t data[16]{};size_t n=size_t(std::min<uint64_t>(16,s->memorySize-(va-s->va)));b.load(va,data,n);Instruction row;row.va=va;row.length=int(std::min(n,d.alignment));row.mnemonic="db";if(d.next(data,n,va)){row.length=d.instruction->size;row.mnemonic=d.instruction->mnemonic;row.operands=d.instruction->op_str;for(auto& c:row.mnemonic)c=char(std::toupper(static_cast<unsigned char>(c)));}for(int k=0;k<row.length;++k){if(k)row.bytes+=' ';row.bytes+=hexchars[data[k]>>4];row.bytes+=hexchars[data[k]&15];}rows.push_back(std::move(row));if(Address(rows.back().length)>UINT64_MAX-va)break;va+=rows.back().length;}return rows;}
Json scanArchitectureCalls(const Binary& b,size_t budget,std::vector<Function>& discovered,const std::function<bool()>& cancelled,bool full){auto start=std::chrono::steady_clock::now();Decoder d(b);uint64_t total=0,scanned=0;size_t examined=0,invalid=0,invalidInstructions=0;std::set<Address> targets;for(auto&s:b.sections){if(!s.executable)continue;auto n=std::min(s.memorySize,s.fileSize);total+=n;for(uint64_t pos=0;pos<n&&(full||examined<budget);){if((examined&1023)==0&&cancelled())throw std::runtime_error("Operation cancelled");size_t take=size_t(std::min<uint64_t>(d.alignment,n-pos));if(d.next(b.bytes()+s.offset+pos,size_t(n-pos),s.va+pos)){take=d.instruction->size;if(auto target=d.callTarget();target&&b.executable(*target))targets.insert(*target);}else{invalid+=take;++invalidInstructions;}pos+=take;scanned+=take;++examined;}}
 for(auto target:targets){auto f=std::lower_bound(b.functions.begin(),b.functions.end(),target,[](const Function&f,Address a){return f.va<a;});if(f==b.functions.end()||f->va!=target)discovered.push_back({target,0,"sub_"+hex(target).substr(2),"direct call target"});}return {{"instructions_examined",examined},{"instructions_decoded",examined-invalidInstructions},{"invalid_bytes",invalid},{"functions_added",discovered.size()},{"scanned_bytes",scanned},{"executable_bytes",total},{"coverage_percent",total?100.0*scanned/total:100.0},{"complete",scanned==total},{"budget_exhausted",!full&&scanned!=total&&examined>=budget},{"cached",false},{"parallel_workers",1},{"full_scan",full},{"scope","linear direct-call discovery in file-backed executable sections"},{"elapsed_ms",std::chrono::duration<double,std::milli>(std::chrono::steady_clock::now()-start).count()}};}
Json architecturesTools(){return Json::array({{{"name","get_architectures"},{"description","List supported input CPUs, formats, and platform limitations."},{"inputSchema",{{"type","object"},{"properties",Json::object()},{"additionalProperties",false}}}},{{"name","open_binary_architecture"},{"description","Open a binary with an explicit raw CPU or ARM/Thumb mode. Structured files retain their declared CPU."},{"inputSchema",{{"type","object"},{"properties",{{"path",{{"type","string"}}},{"architecture",{{"type","string"},{"enum",Json::array({"x86","x64","arm64","arm","thumb","riscv32","riscv64","mips32","mips64"})}}},{"base",{{"type","string"}}}}},{"required",Json::array({"path","architecture"})},{"additionalProperties",false}}}}});}
std::optional<Json> callArchitecturesTool(Engine&e,const std::string& name,const Json& args){if(name=="get_architectures")return Json{{"architectures",Json::array({"x86","x64","arm64","arm","thumb","riscv32","riscv64","mips32","mips64"})},{"formats",Json::array({"PE","ELF little-endian","Mach-O little-endian thin/universal","raw","Windows user-mode minidump"})},{"host_platform","Windows x64"},{"limitations",Json::array({"Only little-endian inputs are supported","ARM ELF Thumb entry points are detected; mixed ARM/Thumb regions require explicit mode selection","Universal Mach-O selects ARM64 when present, otherwise the first supported slice","Kernel dumps and dyld shared caches are not supported"})}};if(name!="open_binary_architecture")return {};auto a=args.at("architecture").get<std::string>();static const std::map<std::string,std::pair<int,std::string>> modes={{"x86",{32,"x86:LE:32:default:gcc"}},{"x64",{64,"x86:LE:64:default:gcc"}},{"arm64",{64,"AARCH64:LE:64:v8A:default"}},{"arm",{32,"ARM:LE:32:v8:default"}},{"thumb",{32,"ARM:LE:32:v8T:default"}},{"riscv32",{32,"RISCV:LE:32:default:gcc"}},{"riscv64",{64,"RISCV:LE:64:default:gcc"}},{"mips32",{32,"MIPS:LE:32:default:default"}},{"mips64",{64,"MIPS:LE:64:default:default"}}};auto it=modes.find(a);if(it==modes.end())throw std::runtime_error("Unsupported architecture");auto path=std::filesystem::u8path(args.at("path").get<std::string>());Binary candidate(path,args.contains("base")?address(args.at("base")):0x1000,it->second.first);auto detected=binaryArchitecture(candidate);if(candidate.format!="Raw"&&detected!=a&&!(detected=="arm"&&a=="thumb")&&!(detected=="thumb"&&a=="arm"))throw std::runtime_error("Requested CPU differs from executable header");e.open(path,args.contains("base")?address(args.at("base")):0x1000,it->second.first);if(candidate.format=="Raw"||a=="arm"||a=="thumb"){e.editableBinary()->language=it->second.second;e.rebuildArchitecture();}return e.binary()->info();}
